using System;using System.IO;using System.Linq;using System.Text;using System.Drawing;using System.IO.Compression;using System.Collections.Generic;using System.Windows.Media.Media3D;
namespace GearLab {
 public static class CADMeshCodec {
  public static string Encode(SceneMesh mesh){using(var memory=new MemoryStream()){using(var compressed=new DeflateStream(memory,CompressionLevel.Optimal,true))using(var writer=new BinaryWriter(compressed)){writer.Write(0x344D5043);writer.Write(mesh.Points.Length);writer.Write(mesh.Indices.Length);for(int i=0;i<mesh.Points.Length;i++){var p=mesh.Points[i];var n=mesh.Normals[i];writer.Write((float)p.X);writer.Write((float)p.Y);writer.Write((float)p.Z);writer.Write((float)n.X);writer.Write((float)n.Y);writer.Write((float)n.Z);}foreach(int i in mesh.Indices)writer.Write(i);}return Convert.ToBase64String(memory.ToArray());}}
  public static SceneMesh Decode(string text){if(text==null||text.Length>64*1024*1024)throw new Exception("Предпросмотр CAD слишком большой.");using(var memory=new MemoryStream(Convert.FromBase64String(text)))using(var compressed=new DeflateStream(memory,CompressionMode.Decompress))using(var r=new BinaryReader(compressed)){if(r.ReadInt32()!=0x344D5043)throw new Exception("Неверный предпросмотр CAD.");int n=r.ReadInt32(),count=r.ReadInt32();if(n<3||n>1500000||count<3||count>1500000||count%3!=0)throw new Exception("Слишком сложная CAD-деталь для встроенного просмотра.");var points=new Point3D[n];var normals=new Vector3D[n];var indices=new int[count];for(int i=0;i<n;i++){points[i]=new Point3D(r.ReadSingle(),r.ReadSingle(),r.ReadSingle());normals[i]=new Vector3D(r.ReadSingle(),r.ReadSingle(),r.ReadSingle());var p=points[i];var v=normals[i];if(!new[]{p.X,p.Y,p.Z,v.X,v.Y,v.Z}.All(MechanismCad.Finite)||new[]{p.X,p.Y,p.Z}.Any(x=>Math.Abs(x)>10000))throw new Exception("Повреждённые координаты CAD.");}for(int i=0;i<count;i++){indices[i]=r.ReadInt32();if(indices[i]<0||indices[i]>=n)throw new Exception("Повреждённые треугольники CAD.");}return new SceneMesh{Points=points,Normals=normals,Indices=indices};}}
 }
 public static class CADNativeBridge {
  public static double[] Transform(Matrix3D m){return new[]{m.M11,m.M21,m.M31,m.OffsetX,m.M12,m.M22,m.M32,m.OffsetY,m.M13,m.M23,m.M33,m.OffsetZ};}
  public static void WriteAssembly(CadAssembly model,string path){using(var kernel=new CADKernel()){var doc=new CADDocument{Name="Сборка GearLab"};var normal=new CadAssembly();foreach(var part in model.Parts){if(part.NativeStep==null){normal.Parts.Add(part);continue;}doc.Features.Add(new CADFeature{Kind="import",Name=part.Label,Data=part.NativeStep,Transform=Transform(part.Placement)});}if(normal.Parts.Count>0){string source=Path.Combine(kernel.Folder,"source.step");StepExport.Write(normal,source);doc.Features.Add(new CADFeature{Kind="import",Name="Параметрические детали",Data=Convert.ToBase64String(File.ReadAllBytes(source))});}kernel.Run(doc,"export_step",path);}}
  public static CADDocument FromLegacyPart(CadPart source){if(source.MeshOverride!=null&&source.NativeStep==null)throw new Exception("У детали только полигональная сетка. Используйте полигональный редактор или восстановите параметрическую деталь.");if(source.NativeStep!=null)return CADDocument.ImportStep(Convert.FromBase64String(source.NativeStep),source.Label);var model=new CadAssembly();var part=new CadPart(source.Id,source.Label,source.Role,source.Color);part.Sections.AddRange(source.Sections);model.Parts.Add(part);string folder=Path.Combine(AppSettings.Folder,"CAD","imports",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);string file=Path.Combine(folder,"part.step");StepExport.Write(model,file);return CADDocument.ImportStep(File.ReadAllBytes(file),source.Label);}
  public static void AppendMove(CADDocument doc,Matrix3D matrix){if(matrix.IsIdentity)return;doc.Features.Add(new CADFeature{Kind="transform",Name="Положение детали",Target=doc.Features.First(f=>f.Kind!="sketch").Id,Transform=Transform(matrix)});}
 }
 public sealed class CADNativeInfo {public string Статус{get{return "Точное CAD-тело с историей";}}public string Редактирование{get{return "Кнопка «CAD Studio: деталь»";}}}
}
